arguments.command:
cd /app/data; python3 - <<'E'
import glob,gzip,re,collections,csv,io
def text(f):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    if b[:3]==b'\xef\xbb\xbf': return b[3:].decode('utf8')
    if b[:2]in(b'\xff\xfe',b'\xfe\xff'): return b.decode('utf16')
    m=re.search(rb'# charset: (\S+)',b[:500])
    return b.decode(m.group(1).decode() if m else 'utf8')
# field-count anomalies
for pat,d in (('east*',','),('lakeside*',','),('river*','\t'),('west*',';'),('harbor*','|')):
    for f in sorted(glob.glob(pat)):
        t=text(f)
        rows=list(csv.reader(io.StringIO(t),delimiter=d,quotechar='"' if d==',' else '\0')) if d==',' else [l.split(d) for l in t.split('\n')]
        hdr=None;n=collections.Counter()
        for r in rows:
            if not r or not r[0].strip(): continue
            if r[0].startswith('#'): continue
            if 'id' in r or 'ref' in r or 'rec' in r: hdr=r;continue
            if hdr and len(r)!=len(hdr): print(f,len(hdr),r)
E

