arguments.command:
cd /app/data; grep -n -B3 'lb' east-w13.csv | head -8; grep -n -m3 -B2 'lb' east-w3.csv | head; python3 - <<'E'
import glob,gzip,re,collections
def text(f):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    return b.decode('latin1')
c=collections.Counter()
for f in sorted(glob.glob('south*')):
    for l in text(f).split('\n'):
        key=(len(l.rstrip('\r')), l[:1] if l[:1] in '#\x0c' else '')
        c[key]+=1
        if l.startswith('#') and not l.startswith(('#LAYOUT FW','#SEQ','#END')) or l.startswith('\x0c'): 
            if c[('x',l[:12])]<2: print(f,repr(l))
            c[('x',l[:12])]+=1
print(sorted(c.items(),key=str)[:40])
E

