def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        exports.setdefault(depot, [])
        try:
            seq, recs = parse_file(depot, path)
        except Exception as e:  # keep going on a damaged export
            print("warning: %s: %s" % (name, e), file=sys.stderr)
            continue
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        files.sort(key=lambda x: (x[0], x[1]))
        cur = {}
        for _, _, recs in files:
            for r in recs:
                if r.kind == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.kind == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    ranked = sorted(current, key=lambda d: (order.get(d, len(order)), d))
    owner = {}
    handovers = 0
    seen_multi = set()
    for d in ranked:
        for num in current[d]:
            if num in owner:
                if num not in seen_multi:
                    seen_multi.add(num)
                    handovers += 1
            else:
                owner[num] = d

    depots = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    for num, d in owner.items():
        r = current[d][num]
        if not counted(r.status) or r.kg is None or r.day is None:
            continue
        depots[d][0] += 1
        depots[d][1] += r.kg
        mk = "%04d-%02d" % (r.day.year, r.day.month)
        mo = months.setdefault(mk, [0, Decimal(0)])
        mo[0] += 1
        mo[1] += r.kg

    def fmt(v):
        return {"shipments": v[0],
                "total_kg": float(v[1].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}

    out = {
        "depots": {d: fmt(v) for d, v in depots.items()},
        "months": {k: fmt(months[k]) for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as fh:
        json.dump(out, fh, indent=2)
        fh.write("\n")


