        if buf.count('"') % 2 == 0:
            yield False, buf
            buf = None
    if buf is not None:
        yield False, buf


def is_header(fields, cols):
    names = [f.strip().lower() for f in fields]
    if len(names) < 2:
        return False
    return all(n in cols or re.fullmatch(r"(gross|net|weight)(_(kg|g|lb|oz))?", n) for n in names)


def parse_delimited(depot, text):
    cfg = DELIM[depot]
    seq = None
    recs = []
    unit_dir = None
    date_dir = None
    comma_dir = False
    hdr = None
    for is_comment, line in logical_lines(text):
        if is_comment:
            body = line[1:].strip()
            if seq is None:
                ms = re.search(r"\bseq\s*[=:]\s*(\d+)", body, re.I)
                if ms:
                    seq = int(ms.group(1))
            md = re.match(r"^([A-Za-z][A-Za-z _\-]*?)\s*[:=]\s*(.*)$", body)
            if md:
                name = md.group(1).strip().lower()
                val = md.group(2).strip()
                if "unit" in name:
                    unit_dir = norm_unit(re.split(r"[\s(]", val)[0]) or unit_dir
                    comma_dir = "decimal comma" in val.lower()
                elif "date" in name:
                    date_dir = val
            continue
        if cfg["quote"]:
            fields = next(csv.reader(io.StringIO(line), delimiter=cfg["delim"]))
        else:
            fields = line.split(cfg["delim"])
        if is_header(fields, cfg["cols"]):
            hdr = [f.strip().lower() for f in fields]
            continue
        if hdr is None:
            continue
        idx = {n: i for i, n in enumerate(hdr)}

        def col(names):
            for n in names:
                if n in idx:
                    return idx[n]
            return None

        wi = None
        for n in hdr:
            if n.startswith("gross"):
                wi = idx[n]
                break
        if wi is None:
            for n in hdr:
                if n.startswith("weight"):
                    wi = idx[n]
                    break
        row_unit = None
        if len(fields) == len(hdr) + 1 and wi is not None:
            cand = norm_unit(fields[wi + 1]) if wi + 1 < len(fields) else None
            if cand:
                row_unit = cand
                fields = fields[:wi + 1] + fields[wi + 2:]
            else:
                for j, f in enumerate(fields):
                    if j != wi and norm_unit(f) and f.strip().lower() in UNIT_KG:
                        row_unit = norm_unit(f)
                        fields = fields[:j] + fields[j + 1:]
                        break
        fields = fields + [""] * (len(hdr) - len(fields))

        def get(names):
            i = col(names)
            return fields[i] if i is not None and i < len(fields) else ""

        kind = norm_type(get(TYPE_COLS))
        col_unit = None
        if wi is not None:
            mu = re.search(r"_(kg|g|lb|oz)$", hdr[wi])
            col_unit = mu.group(1) if mu else None
        comma = cfg.get("comma", False) or comma_dir
        form = date_dir or None
        rec = make_rec(
            kind, get(ID_COLS),
            lambda: parse_weight(fields[wi], unit_dir, comma, col_unit or row_unit),
            lambda: parse_date(get(DATE_COLS), form),
            get(STATUS_COLS))
        if rec and depot == "harbor":
            rec.status = {"dlv": "delivered", "dll": "delivered_late"}.get(rec.status, rec.status)
        if rec:
            recs.append(rec)
    return seq, recs


# -------------------------------------------------------------- fixed width
LAYOUTS = {
    "FW1": (42, lambda l: (l[9], l[0:9], l[10:17], l[17:25], l[25], "yyyyddd", Decimal("0.001"))),
    "FW2": (43, lambda l: (l[0], l[1:10], l[10:18], l[18:26], l[26], "yyyymmdd", Decimal("0.01"))),
    "FW3": (41, lambda l: (l[16], l[0:9], l[9:16], l[17:24], l[24], "yyyyddd",
                           Decimal("0.1") * UNIT_KG["lb"])),
}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}


def parse_fixed(text):
    seq = None
    recs = []
    layout = None
    by_len = {v[0]: k for k, v in LAYOUTS.items()}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if line.startswith("\x0c") or not line.strip():
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\w+)", line, re.I)
            if m and m.group(1).upper() in LAYOUTS:
                layout = m.group(1).upper()
            m = re.match(r"#SEQ\s+(\d+)", line, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        name = by_len.get(len(line))
        if name is None:
            if layout and len(line) < LAYOUTS[layout][0]:
                name = layout
                line = line.ljust(LAYOUTS[layout][0])
            else:
                continue
        t, rid, shipped, weight, st, dform, factor = LAYOUTS[name][1](line)
        rec = make_rec(
            norm_type(t), rid,
            lambda: Decimal(int(weight)) * factor,
            lambda: parse_date(shipped, dform),
            FW_STATUS.get(st.strip().upper(), st.strip()))
        if rec:
            recs.append(rec)
    return seq, recs


# ---------------------------------------------------------------------- XML
def xget(el, name):
    if name in el.attrib:
        return el.attrib[name]
    ch = el.find(name)
    if ch is not None:
        return (ch.text or "").strip()
    return None


def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if (root.get("seq") or "").isdigit() else None
    root_unit = norm_unit(root.get("weight-unit") or root.get("weight_unit") or root.get("unit"))
    recs = []
    for el in root.iter("shipment"):
        kind = norm_type(el.get("type"))

        def weight():
            w = el.find("weight")
            txt = w.text if w is not None else el.get("weight")
            unit = (norm_unit(w.get("unit")) if w is not None else None) \
                or norm_unit(el.get("weight-unit") or el.get("weight_unit") or el.get("unit"))
            return parse_weight(txt, root_unit, False, unit)

        rec = make_rec(kind, el.get("id") or xget(el, "id"), weight,
                       lambda: parse_date(xget(el, "shipped") or xget(el, "shipped_at")),
                       xget(el, "status"))
        if rec:
            recs.append(rec)
    return seq, recs


# --------------------------------------------------------------------- JSON
def parse_jsonl(text):
    seq = None
    recs = []
    meta_unit = None
    items = []
    for line in text.split("\n"):
        line = line.strip().lstrip("﻿")
        if not line or line.startswith("#"):
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        items.extend(v if isinstance(v, list) else [v])
    for o in items:
        if not isinstance(o, dict):
            continue
        if "meta" in o and isinstance(o["meta"], dict):
            if seq is None and o["meta"].get("seq") is not None:
                seq = int(o["meta"]["seq"])
            meta_unit = norm_unit(o["meta"].get("weight_unit") or o["meta"].get("unit")) or meta_unit
    for o in items:
        if not isinstance(o, dict) or "meta" in o:
            continue

        def weight():
            for k, v in o.items():
                m = re.fullmatch(r"weight(?:_(kg|g|lb|oz))?", k, re.I)
                if m:
                    unit = norm_unit(m.group(1)) or norm_unit(o.get("unit") or o.get("weight_unit"))
                    if isinstance(v, str):
                        return parse_weight(v, meta_unit, False, unit)
                    return Decimal(str(v)) * UNIT_KG[unit or meta_unit or "kg"]
            raise ValueError("no weight")

        rec = make_rec(norm_type(o.get("kind")), str(o.get("id", "")), weight,
                       lambda: parse_date(o.get("shipped_at") or o.get("shipped")),
                       o.get("status"))
        if rec:
            recs.append(rec)
    return seq, recs


# --------------------------------------------------------------------- main
def parse_file(depot, path):
    b = read_bytes(path)
    stripped = b.lstrip(b"\xef\xbb\xbf\xff\xfe\xfe\xff\x00 \t\r\n")[:1]
    if depot == "central" or stripped == b"<":
        if stripped == b"<":
            return parse_xml(b)
    text = decode(b)
    first = text.lstrip("﻿ \t\r\n")[:1]
    if depot in DELIM:
        return parse_delimited(depot, text)
    if depot == "south":
        return parse_fixed(text)
    if depot == "north" or first in "{[":
        return parse_jsonl(text)
    if first == "<":
        return parse_xml(b)
    if "#LAYOUT" in text:
        return parse_fixed(text)
    raise ValueError("unknown format for " + path)


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0].lower()
        exports.setdefault(depot, [])
        try:
            seq, recs = parse_file(depot, path)
        except Exception as e:  # keep going on a damaged export
            print("warning: %s: %s" % (name, e), file=sys.stderr)
            continue
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        files.sort(key=lambda x: (x[0], x[1]))
        cur = {}
        for _, _, recs in files:
            for r in recs:
                if r.kind == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.kind == "correction":
                    cur[r.num] = r
                    corrections += 1
                else:
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    ranked = sorted(current, key=lambda d: (order.get(d, len(order)), d))
    owner = {}
    handovers = 0
    seen_multi = set()
    for d in ranked:
        for num in current[d]:
            if num in owner:
                if num not in seen_multi:
                    seen_multi.add(num)
                    handovers += 1
            else:
                owner[num] = d

    depots = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    for num, d in owner.items():
        r = current[d][num]
        if not counted(r.status) or r.kg is None or r.day is None:
            continue
        depots[d][0] += 1
        depots[d][1] += r.kg
        mk = "%04d-%02d" % (r.day.year, r.day.month)
        mo = months.setdefault(mk, [0, Decimal(0)])
        mo[0] += 1
        mo[1] += r.kg

    def fmt(v):
        return {"shipments": v[0],
                "total_kg": float(v[1].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}

    out = {
        "depots": {d: fmt(v) for d, v in depots.items()},
        "months": {k: fmt(months[k]) for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as fh:
        json.dump(out, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: summarize.py DATA_DIR OUT_FILE")
    main(sys.argv[1], sys.argv[2])
